using LogbookSqlServer.Models; using Microsoft.EntityFrameworkCore;
namespace LogbookSqlServer.Data;
public class LogbookDbContext(DbContextOptions<LogbookDbContext> options):DbContext(options) { public DbSet<AppUser> Users=>Set<AppUser>(); public DbSet<Beneficiary> Beneficiaries=>Set<Beneficiary>(); public DbSet<BeneficiaryMedia> BeneficiaryMedia=>Set<BeneficiaryMedia>(); public DbSet<HouseholdMember> HouseholdMembers=>Set<HouseholdMember>(); protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<AppUser>().HasIndex(x=>x.Username).IsUnique();b.Entity<BeneficiaryMedia>().HasOne(x=>x.Beneficiary).WithMany().HasForeignKey(x=>x.BeneficiaryId).OnDelete(DeleteBehavior.Cascade);b.Entity<HouseholdMember>().HasOne(x=>x.Beneficiary).WithMany().HasForeignKey(x=>x.BeneficiaryId).OnDelete(DeleteBehavior.Cascade);b.Entity<HouseholdMember>().Property(x=>x.MonthlyIncome).HasPrecision(18,2);b.Entity<Beneficiary>().HasIndex(x=>x.CitizenId);b.Entity<Beneficiary>().Property(x=>x.AnnualBudget).HasPrecision(18,2);b.Entity<Beneficiary>().Property(x=>x.HouseholdIncome).HasPrecision(18,2);} }